<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body {
    height: 100%;
    background: #0d1117;
    color: #e6edf3;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
  }
  body {
    flex-direction: column;
    gap: 16px;
    padding: 20px;
  }
  h1 {
    font-size: 18px;
    font-weight: 500;
    color: #8b949e;
    letter-spacing: 0.5px;
  }
  #sim {
    background: #161b22;
    border: 1px solid #30363d;
    border-radius: 8px;
    display: block;
    cursor: crosshair;
    box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  }
  .controls {
    display: flex;
    gap: 10px;
  }
  button {
    background: #21262d;
    color: #e6edf3;
    border: 1px solid #30363d;
    padding: 8px 18px;
    border-radius: 6px;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
    font-family: inherit;
  }
  button:hover {
    background: #30363d;
    border-color: #8b949e;
  }
  button:active {
    background: #1f6feb;
    border-color: #1f6feb;
  }
  .info {
    font-size: 12px;
    color: #6e7681;
  }
</style>
</head>
<body>
  <h1>Bouncing Ball Physics Playground</h1>
  <canvas id="sim" width="500" height="500"></canvas>
  <div class="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Pause</button>
    <button id="clear">Clear</button>
  </div>
  <div class="info">Click the canvas to add a ball</div>

<script>
(function () {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');

  // Logical / rendering size — use CSS pixels for size, but back the canvas
  // with a matching internal resolution.
  const W = canvas.width;
  const H = canvas.height;

  // Simulation state
  const balls = [];
  const GRAVITY = 0.5;
  const RESTITUTION = 0.85;
  const AIR_FRICTION = 0.999;
  const MAX_SUBSTEPS = 8;

  // Animation
  let playing = true;
  let lastTime = performance.now();
  let rafId = null;

  // ---------- API ----------
  window.sim = {
    w: W,
    h: H,
    balls() {
      return balls.map(b => ({
        x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r
      }));
    },
    addBall(x, y, vx = 0, vy = 0, r) {
      const radius = (typeof r === 'number' && r > 0) ? r : 10 + Math.random() * 8;
      balls.push({
        x: x,
        y: y,
        vx: vx,
        vy: vy,
        r: radius,
        color: `hsl(${Math.random() * 360}, 70%, 60%)`
      });
      return balls[balls.length - 1];
    },
    clear() {
      balls.length = 0;
      draw();
    },
    step(dt = 1) {
      simulate(dt);
      draw();
    }
  };

  // ---------- Physics ----------
  function simulate(dt) {
    // Substepping to prevent tunneling at high velocities.
    // We pick the number of substeps based on the fastest ball.
    let maxSpeed = 0;
    for (let i = 0; i < balls.length; i++) {
      const s = Math.abs(balls[i].vx) + Math.abs(balls[i].vy);
      if (s > maxSpeed) maxSpeed = s;
    }
    let steps = Math.ceil(maxSpeed / 6);
    if (steps < 1) steps = 1;
    if (steps > MAX_SUBSTEPS) steps = MAX_SUBSTEPS;
    const subDt = dt / steps;

    for (let s = 0; s < steps; s++) {
      for (let i = 0; i < balls.length; i++) {
        const b = balls[i];
        // Apply gravity
        b.vy += GRAVITY * subDt;
        // Air friction (very mild)
        b.vx *= AIR_FRICTION;
        b.vy *= AIR_FRICTION;

        // Move
        b.x += b.vx * subDt;
        b.y += b.vy * subDt;

        // Collide with walls — clamp first to keep the ball fully inside,
        // then reverse the perpendicular component with energy loss.
        if (b.x - b.r < 0) {
          b.x = b.r;
          if (b.vx < 0) b.vx = -b.vx * RESTITUTION;
        } else if (b.x + b.r > W) {
          b.x = W - b.r;
          if (b.vx > 0) b.vx = -b.vx * RESTITUTION;
        }
        if (b.y - b.r < 0) {
          b.y = b.r;
          if (b.vy < 0) b.vy = -b.vy * RESTITUTION;
        } else if (b.y + b.r > H) {
          b.y = H - b.r;
          if (b.vy > 0) b.vy = -b.vy * RESTITUTION;
        }
      }
    }
  }

  // ---------- Rendering ----------
  function draw() {
    // Background
    ctx.fillStyle = '#161b22';
    ctx.fillRect(0, 0, W, H);

    // Subtle grid for atmosphere
    ctx.strokeStyle = 'rgba(48, 54, 61, 0.4)';
    ctx.lineWidth = 1;
    const grid = 25;
    ctx.beginPath();
    for (let x = grid; x < W; x += grid) {
      ctx.moveTo(x, 0); ctx.lineTo(x, H);
    }
    for (let y = grid; y < H; y += grid) {
      ctx.moveTo(0, y); ctx.lineTo(W, y);
    }
    ctx.stroke();

    // Balls
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      // Soft glow
      const grad = ctx.createRadialGradient(
        b.x - b.r * 0.3, b.y - b.r * 0.3, b.r * 0.1,
        b.x, b.y, b.r
      );
      grad.addColorStop(0, '#ffffff');
      grad.addColorStop(0.3, b.color);
      grad.addColorStop(1, shadeColor(b.color, -30));
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fill();

      // Outline
      ctx.strokeStyle = 'rgba(255,255,255,0.25)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }

  function shadeColor(hsl, percent) {
    // Simple shade: parse hsl and adjust lightness
    const m = hsl.match(/hsl\((\d+),\s*(\d+)%,\s*(\d+)%\)/);
    if (!m) return hsl;
    let l = parseInt(m[3], 10) + percent;
    if (l < 0) l = 0;
    if (l > 100) l = 100;
    return `hsl(${m[1]}, ${m[2]}%, ${l}%)`;
  }

  // ---------- Animation loop ----------
  function loop(now) {
    const dtMs = now - lastTime;
    lastTime = now;
    // Clamp dt to avoid huge jumps when tab regains focus
    const dt = Math.min(dtMs / 16.6667, 3);
    if (playing) {
      simulate(dt);
    }
    draw();
    rafId = requestAnimationFrame(loop);
  }

  // ---------- Input ----------
  canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    // Small random kick for satisfying feel
    const vx = (Math.random() - 0.5) * 4;
    const vy = (Math.random() - 0.5) * 4;
    window.sim.addBall(x, y, vx, vy);
  });

  document.getElementById('drop').addEventListener('click', () => {
    const x = W / 2 + (Math.random() - 0.5) * 40;
    const y = 30;
    window.sim.addBall(x, y, (Math.random() - 0.5) * 3, 0);
  });

  document.getElementById('play').addEventListener('click', (e) => {
    playing = !playing;
    e.target.textContent = playing ? 'Pause' : 'Play';
  });

  document.getElementById('clear').addEventListener('click', () => {
    window.sim.clear();
  });

  // ---------- Init ----------
  // Seed with a couple of balls so it's not empty on load
  window.sim.addBall(W / 2 - 40, 60, 2, 0);
  window.sim.addBall(W / 2 + 40, 60, -2, 0);

  draw();
  rafId = requestAnimationFrame(loop);
})();
</script>
</body>
</html>
